		option.WithAPIKey("My API Key"),
	)
	result, err := client.Realtime.Calls.New(
		context.TODO(),
		openai.RealtimeCallNewParams{
			Sdp: "string",
			Session: openai.RealtimeSessionCreateRequestGa{Type: "realtime", OutputModalities: []openai.RealtimeSessionCreateRequestGaOutputModalitiesItem{"audio"}, Model: "string", Instructions: "string", Audio: openai.RealtimeSessionCreateRequestGaAudio{Input: openai.RealtimeSessionCreateRequestGaAudioInput{Format: openai.RealtimeAudioFormatsAudioPcm{Type: "audio/pcm", Rate: 24000}, Transcription: openai.AudioTranscription{Model: "string", Language: "string", Prompt: "string", Delay: openai.AudioTranscriptionDelayMinimal}, NoiseReduction: openai.RealtimeSessionCreateRequestGaAudioInputNoiseReduction{Type: openai.NoiseReductionTypeNearField}, TurnDetection: openai.RealtimeTurnDetectionServerVad{Type: "server_vad", Threshold: 1, PrefixPaddingMs: 1, SilenceDurationMs: 1, CreateResponse: true, InterruptResponse: true, IdleTimeoutMs: 1}}, Output: openai.RealtimeSessionCreateRequestGaAudioOutput{Format: openai.RealtimeAudioFormatsAudioPcm{Type: "audio/pcm", Rate: 24000}, Voice: "string", Speed: 1}}, Include: []string{"item.input_audio_transcription.logprobs"}, Tracing: "auto", Tools: []openai.RealtimeSessionCreateRequestGaToolsItem{openai.RealtimeFunctionTool{Type: "function", Name: "string", Description: "string", Parameters: map[string]any{"key": nil}}}, ToolChoice: openai.ToolChoiceOptionsNone, ParallelToolCalls: true, Reasoning: openai.RealtimeReasoning{Effort: openai.RealtimeReasoningEffortMinimal}, MaxOutputTokens: 1, Truncation: openai.RealtimeTruncationStringAuto, Prompt: openai.Prompt{ID: "string", Version: "string", Variables: map[string]openai.ResponsePromptVariablesValue{"key": "string"}}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
